#!/usr/bin/env bash
# Adds ZK chunks on People.
set -euo pipefail
source ./load-config.sh

# R2e9: 3 pages
R2e9_
R2e9_
R2e9_
R2e9_PAGES=("$R2e9_PAGE0" "$R2e9_PAGE1" "$R2e9_PAGE2")

for page_idx in "${!R2e9_PAGES[@]}"; do
  page_value="${R2e9_PAGES[$page_idx]}"

  page_state=$(dot people.query.ChunksManager.Chunks R2e9 $page_idx)
  if [[ "$page_state" != "undefined" ]]; then
    echo "Skipping R2e9 page $page_idx: chunks already set"
    continue
  fi

  echo "Adding R2e9 page $page_idx..."
  add_chunks_call=$(dot --encode people.tx.ChunksManager.add_chunks R2e9 "$page_idx" "$page_value")
  dispatch_call=$(dot --encode people.tx.Utility.dispatch_as '{"type":"system","value":{"type":"Authorized"}}' "$add_chunks_call")
  dot people.tx.Sudo.sudo "$dispatch_call" --from "$SIGNER_PEOPLE_SUDO"
done

# R2e10: 5 pages
R2e10_
R2e10_
R2e10_
R2e10_
R2e10_
R2e10_PAGES=("$R2e10_PAGE0" "$R2e10_PAGE1" "$R2e10_PAGE2" "$R2e10_PAGE3" "$R2e10_PAGE4")

for page_idx in "${!R2e10_PAGES[@]}"; do
  page_value="${R2e10_PAGES[$page_idx]}"

  page_state=$(dot people.query.ChunksManager.Chunks R2e10 $page_idx)
  if [[ "$page_state" != "undefined" ]]; then
    echo "Skipping R2e10 page $page_idx: chunks already set"
    continue
  fi

  echo "Adding R2e10 page $page_idx..."
  add_chunks_call=$(dot --encode people.tx.ChunksManager.add_chunks R2e10 "$page_idx" "$page_value")
  dispatch_call=$(dot --encode people.tx.Utility.dispatch_as '{"type":"system","value":{"type":"Authorized"}}' "$add_chunks_call")
  dot people.tx.Sudo.sudo "$dispatch_call" --from "$SIGNER_PEOPLE_SUDO"
done
